NO_GAME_PHOTO |= set(["inu.ks-g-scent", "inu.ks-g-sight", "inu.ks-kogata", "inu.ks-zasshu", "inu.ks-toypoodle", "inu.ks-bloodhound", "inu.ks-chugata", "inu.ks-oogata", "inu.ks-giantschnauzer", "inu.ks-kuroshiba", "inu.ks-shiroshiba"])
SKIP_PREFIX = {"cabin": ("ky-", "ma-", "sh-", "ei-"),
               "inu": ("sg-", "nk-", "ym-", "kr-", "st-", "km-", "kd-", "rk-", "az-", "kk-")}  # フリック犬の気持ち(2026-10-24): 写真は 犬種図鑑だけ(しぐさは コードの 図。体・こころの 写真は 出さない)
SKIP_FIELD = {"supercar": ("人",)}  # スーパーカーは 人の 語の 写真を 取らない(実在の 人の 顔写真は 入れない。2026-10-21)


def main():
    only = [a for a in sys.argv[1:] if not a.startswith("--")]
    games = [g for g in GAMES if not only or g in only]
    cache = json.loads((ROOT / "tools" / "wiki-titles.json").read_text(encoding="utf-8"))
    S.SERIES.clear()
    for g in games:
        for t in json.loads((ROOT / "data" / f"{g}.json").read_text(encoding="utf-8"))["terms"]:
            title = cache.get(t["name"])
            key = f"{g}.{t['id']}"
            if t["id"].startswith(SKIP_PREFIX.get(g, ("\0",))): continue
            if t.get("field") in SKIP_FIELD.get(g, ()): continue
            if title or key in GAME_PICKS:
                S.SERIES[key] = (title or t["name"], t["name"], g)
    S.NO_PHOTO |= NO_GAME_PHOTO
    S.PICKS.update(GAME_PICKS)
    print(len(S.SERIES), "語に Wikipedia の 記事", flush=True)
    sys.argv = sys.argv[:1] + [a for a in sys.argv[1:] if a.startswith("--")]
    S.main()


if __name__ == "__main__":
    main()
